-- grounds: old seeded district/city pairs -> refreshed names (city-specific rows first)
UPDATE grounds SET district = 'NTR', city = 'Vijayawada' WHERE state = 'Andhra Pradesh' AND district = 'Krishna' AND city = 'Vijayawada';
UPDATE grounds SET district = 'Tirupati', city = 'Tirupati' WHERE state = 'Andhra Pradesh' AND district = 'Chittoor' AND city = 'Tirupati';
UPDATE grounds SET district = 'Kamrup Metro', city = 'Guwahati' WHERE state = 'Assam' AND district = 'Kamrup Metropolitan' AND city = 'Dispur';
UPDATE grounds SET district = 'Kamrup Metro' WHERE state = 'Assam' AND district = 'Kamrup Metropolitan';
UPDATE grounds SET district = 'Mumbai' WHERE state = 'Maharashtra' AND district = 'Mumbai City';
UPDATE grounds SET district = 'Chhatrapati Sambhajinagar' WHERE state = 'Maharashtra' AND district = 'Aurangabad';
UPDATE grounds SET district = 'Gangtok' WHERE state = 'Sikkim' AND district = 'East Sikkim';
UPDATE grounds SET district = 'Hanumakonda' WHERE state = 'Telangana' AND district = 'Warangal Urban';
UPDATE grounds SET district = 'Gautam Buddha Nagar' WHERE state = 'Uttar Pradesh' AND district = 'Gautam Buddh Nagar';
UPDATE grounds SET district = 'South Andamans' WHERE state = 'Andaman and Nicobar Islands' AND district = 'South Andaman';

-- Reseed. Deleting districts cascades to cities (V5 FK ON DELETE CASCADE); nothing else references either.
DELETE FROM districts;

